    as seen here: https://github.com/multinormal/ddsm/blob/master/ddsm-software/get_ddsm_groundtruth.m
    original documentation: http://marathon.csee.usf.edu/Mammography/DDSM/case_description.html#OVERLAYFILE
    rows and columns are swapped
    """
def path_to_directions(l: Any) -> object {
    chain_code = {
        0: [-1, 0],
        1: [-1, 1],
        2: [0, 1],
        3: [1, 1],
        4: [1, 0],
        5: [1, -1],
        6: [0, -1],
        7: [-1, -1]
    };
    return [chain_code[x] for x in l];
}

"""
    Return list of all the slices.

    Example
    -------
    >>> _slice_list((slice(1,2), slice(1,3), 2, slice(2,4), 8))
    [slice(1, 2, None), slice(1, 3, None), slice(2, 3, None), slice(2, 4, None), slice(8, 9, None)]
    """
def _slice_list(`obj: Any) -> object {
    result = [];
    if not isinstance(`obj, (`tuple, `list)) {
        return result;
    }
    for (i, o) in enumerate(`obj) {
        if isinstance(o, int) {
            result.append(slice(o, (o + 1)));
        } elif isinstance(o, slice) {
            result.append(o);
        }
    }
    return result;
}

